"""Update current project handoffs after audited Session A; preserve past reports."""
from pathlib import Path
import json
import hashlib
import datetime
import re
ROOT=Path(__file__).resolve().parents[1]

def insert(name,text):
    p=ROOT/name; old=p.read_text(encoding='utf-8')
    if text in old or (text.startswith('## ') and text.split('\n')[0] in old): return
    first,rest=old.split('\n',1); p.write_text(first+'\n\n'+text+'\n\n'+rest.lstrip('\n'),encoding='utf-8')

def main():
    a=json.loads((ROOT/'results/exp009/analysis.json').read_text()); assert a['all_archives_replayed_exactly']
