        for before,after in [('Figure4','Figure 4'),('within1.17','within 1.17'),('all152','all 152'),('has5x','has 5x'),('use5x','use 5x'),('is5x','is 5x'),('are5x','are 5x'),('versus4.5x','versus 4.5x'),('uses4.5x','uses 4.5x'),('says4.5x','says 4.5x'),('a5x','a 5x'),('exit0','exit 0'),('commit9f3','commit 9f3'),('Octave11.3','Octave 11.3'),('error1.17','error 1.17'),('eta.001','eta .001'),('fixed24','fixed 24'),('All152','All 152')]: text=text.replace(before,after)
